css:
.print-format {
  page-size: A4;
  orientation: Landscape;
  margin-top: 5mm;
  margin-right: 5mm;
  margin-bottom: 5mm;
  margin-left: 5mm;
  padding: 0 !important;
}

@media screen {
  .print-format {
    max-width: 297mm;
    min-height: 141.2mm;
  }
}

@page {
  size: 297mm 141.2mm;
  margin: 5mm;
}

html:
{# ============================================================
   ITO HALL TICKET — PRINT FORMAT
   ============================================================ #}


{# ============================================================
   DIRECT STUDENT FIELDS
   ============================================================ #}

{% set school_code   = doc.get("ito_school_code") or "" %}
{% set student_class = doc.get("class") or "" %}
{% set roll_no       = doc.get("roll_no") or "" %}
{% set academic_year = doc.get("academic_year") or "" %}
{% set student_name  = (doc.get("student_name") or "")|upper %}
{% set school_name   = (doc.get("full_name") or "")|upper %}


{# ============================================================
   CITY / STATE
   ============================================================ #}

{% set addr = frappe.db.sql("""
    SELECT
        addr.city,
        addr.state
    FROM `tabAddress` addr
    INNER JOIN `tabDynamic Link` dl
        ON dl.parent = addr.name
    WHERE
        dl.link_doctype = 'Customer'
        AND dl.link_name = %s
    ORDER BY
        addr.is_primary_address DESC,
        addr.modified DESC
    LIMIT 1
""", doc.school, as_dict=True) if doc.school else [] %}

{% set city_state =
    ((addr[0].city or "") ~ ", " ~ (addr[0].state or ""))|upper
    if addr else ""
%}


{# ============================================================
   EXAM SLOT + DATE DATA
   ============================================================ #}

{% set exam_data = get_exam_slot_summary(doc) %}

{% set slots = exam_data.get("slots", {}) %}
{% set exam_dates = exam_data.get("dates", {}) %}


<style>

/* ============================================================
   PAGE
   ============================================================ */

@page {
    size: 297mm 141.2mm;
    margin: 5mm;
}

.print-format {
    margin: 0 !important;
    padding: 0 !important;
}


/* ============================================================
   MAIN HALL TICKET
   ============================================================ */

.ito-hall-ticket {
    position: relative;

    width: 287mm;
    height: 131.2mm;

    margin: 0 auto;

    overflow: hidden;

    background: #ffffff;

    page-break-inside: avoid;

    font-family: Arial, Helvetica, sans-serif;

    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}


/* ============================================================
   BACKGROUND
   ============================================================ */

.ito-hall-ticket .ticket-background {
    position: absolute;

    left: 0;
    top: 0;

    width: 100%;
    height: 100%;

    z-index: 1;

    display: block;
}


/* ============================================================
   COMMON DYNAMIC TEXT
   ============================================================ */

.ito-hall-ticket .ticket-value {
    position: absolute;

    z-index: 5;

    color: #0b1f64;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 17px;

    font-weight: 600;

    line-height: 1;

    white-space: nowrap;

    letter-spacing: 0;
}


/* ============================================================
   STUDENT INFORMATION
   ============================================================ */

.ito-hall-ticket .school-code {
    left: 30.20%;
    top: 21.35%;
}

.ito-hall-ticket .class-value {
    left: 46.00%;
    top: 21.35%;
}

.ito-hall-ticket .roll-no {
    left: 60.45%;
    top: 21.35%;
}

.ito-hall-ticket .academic-year {
    left: 51.8%;
    top: 27.65%;
}

.ito-hall-ticket .student-name {
    left: 30.20%;
    top: 28.10%;
}

.ito-hall-ticket .school-name {
    left: 30.20%;
    top: 34.75%;
}

.ito-hall-ticket .city-state {
    left: 30.20%;
    top: 41.45%;
}


/* ============================================================
   EXAM SLOT INFORMATION

   Aligned with the left edge of:
       "Exams & Slot selected"
   ============================================================ */

.ito-hall-ticket .slot-a {
    position: absolute;

    left: 16.15%;
    top: 58.90%;

    z-index: 5;

    color: #0b1f64;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 15px;

    font-weight: 600;

    line-height: 1.45;

    white-space: nowrap;

    letter-spacing: 0;
}

.ito-hall-ticket .slot-a > div {
    margin-left: 19px;
    padding: 0;
}


/* ============================================================
   EXAM PANEL
   ============================================================ */

.ito-hall-ticket .exam-panel {
    position: absolute;
    left: 73.15%;
    top: 0.6%;
    width: 26.25%;
    height: 71.4%;
    z-index: 4;
    box-sizing: border-box;
    background: #ffffff;
    border: 2px solid #a8dcf5;
    border-radius: 0 9px 0 0;
    overflow: hidden;
}

.ito-hall-ticket .exam-panel table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

/* Header */
.ito-hall-ticket .exam-panel th {
    height: 8mm;
    background: linear-gradient(180deg, #4a3a9e 0%, #2f2272 100%);
    color: #ffffff;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: .2px;
    text-align: center;
    vertical-align: middle;
    white-space: nowrap;
}

.ito-hall-ticket .exam-panel th.dt {
    background: linear-gradient(180deg, #33267f 0%, #221860 100%);
    border-left: 1px solid #a8dcf5;
}

/* Rows (height is set inline on each <tr>) */
.ito-hall-ticket .exam-panel td {
    height: auto;
    padding: 0 4px !important;
    border-bottom: 1px solid #cfe9f8;
    vertical-align: middle !important;
    overflow: hidden;
}
.ito-hall-ticket .exam-panel th {
    vertical-align: middle !important;
    padding: 0 !important;
}

.ito-hall-ticket .exam-panel tbody tr:nth-child(even) td {
    background: #f2faff;
}

.ito-hall-ticket .exam-panel .c-code {
    width: 19%;
    padding-left: 6px !important;
}

.ito-hall-ticket .exam-panel .c-date {
    width: 27%;
    text-align: center;
    border-left: 1px solid #cfe9f8;
}

/* Filler row: absorbs leftover space when there are few exams */
.ito-hall-ticket .exam-panel tr.filler td {
    background: #ffffff !important;
    border-bottom: none;
    border-left: none;
    padding: 0;
}

/* Code chip */
.ito-hall-ticket .exam-panel .code {
    display: block;
    padding: 2px 0;
    border-radius: 5px;
    color: #ffffff;
    font-size: 10.5px;
    font-weight: 700;
    text-align: center;
    letter-spacing: .3px;
    box-shadow: inset 0 -2px 0 rgba(0,0,0,.18);
}

/* Exam name */
.ito-hall-ticket .exam-panel .name {
    padding-left: 6px;
    font-size: 9px;
    font-weight: 600;
    line-height: 1.1;
    color: #1b2a6b;
}

/* Date */
.ito-hall-ticket .exam-panel .date {
    font-size: 11.5px;
    font-weight: 700;
    color: #0b1f64;
    white-space: nowrap;
}
/* Large rows (1-5 exams) */
.ito-hall-ticket .exam-panel.sz-lg .code { font-size: 13px; padding: 6px 0; }
.ito-hall-ticket .exam-panel.sz-lg .name { font-size: 12px; line-height: 1.2; padding-left: 8px; }
.ito-hall-ticket .exam-panel.sz-lg .date { font-size: 13px; }

/* Medium rows (6-8 exams) */
.ito-hall-ticket .exam-panel.sz-md .code { font-size: 11.5px; padding: 3px 0; }
.ito-hall-ticket .exam-panel.sz-md .name { font-size: 10.5px; line-height: 1.15; }
.ito-hall-ticket .exam-panel.sz-md .date { font-size: 12px; }


/* ============================================================
   PAGE LABEL
   ============================================================ */

.ito-hall-ticket .page-label {
    position: absolute;

    right: 3.0%;
    top: 86.5%;

    left: auto;

    z-index: 5;

    color: #0b1f64;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 15px;

    font-weight: 700;

    line-height: 1;

    text-align: right;

    white-space: nowrap;
}


/* ============================================================
   PRINT
   ============================================================ */

@media print {

    .ito-hall-ticket {
        width: 287mm !important;
        height: 131.2mm !important;

        margin: 0 auto !important;
    }

}

</style>


<div class="ito-hall-ticket">


    {# ========================================================
       BACKGROUND TEMPLATE
       ======================================================== #}

    <img
        class="ticket-background"
        src="/files/ito_hall_ticket.png"
        alt="Hall Ticket Template"
    >


    {# ========================================================
       STUDENT DETAILS
       ======================================================== #}

    <div class="ticket-value school-code">
        {{ school_code }}
    </div>

    <div class="ticket-value class-value">
        {{ student_class }}
    </div>

    <div class="ticket-value roll-no">
        {{ roll_no }}
    </div>

    {% if academic_year %}
    <div class="ticket-value academic-year">
        Academic Year : {{ academic_year }}
    </div>
    {% endif %}

    <div class="ticket-value student-name">
        {{ student_name }}
    </div>

    <div class="ticket-value school-name">
        {{ school_name }}
    </div>

    <div class="ticket-value city-state">
        {{ city_state }}
    </div>


    {# ========================================================
       EXAM SLOTS

       Example:

       SLOT A : CIO
       SLOT B : ICO
       SLOT C : IDO
       ======================================================== #}

    <div class="ticket-value slot-a">

        {% if slots.get("A") %}
            <div>
                SLOT A : {{ slots.get("A") | join(", ") }}
            </div>
        {% endif %}

        {% if slots.get("B") %}
            <div>
                SLOT B : {{ slots.get("B") | join(", ") }}
            </div>
        {% endif %}

        {% if slots.get("C") %}
            <div>
                SLOT C : {{ slots.get("C") | join(", ") }}
            </div>
        {% endif %}

        {% if slots.get("Other") %}
            <div>
                OTHER : {{ slots.get("Other") | join(", ") }}
            </div>
        {% endif %}

    </div>


    {# ========================================================
       EXAM DATES

       The exam names are already present in the PNG.

       These values only overlay:
           Exam Summary CT.slot_date

       against the corresponding exam.
       ======================================================== #}

    {% set reg = [] %}
    {% for k, codes in slots.items() %}
        {% for c in codes %}{% set _ = reg.append(c) %}{% endfor %}
    {% endfor %}

    {% set exams = [
        ("ISO",  "Science Olympiad",                      "#e53935"),
        ("IMO",  "Maths Olympiad",                        "#1e7ad6"),
        ("EIO",  "English Olympiad",                      "#f28a13"),
        ("GKIO", "General Knowledge Olympiad",            "#8a63c9"),
        ("ICO",  "Computer Olympiad",                     "#10acc9"),
        ("IDO",  "Drawing Olympiad",                      "#16b38a"),
        ("NESO", "Essay Olympiad",                        "#e5245f"),
        ("NSSO", "Science &amp; Social Studies Olympiad", "#f7931e"),
        ("NLRO", "Logical Reasoning Olympiad",            "#4b2c8f"),
        ("NHO",  "Hindi Olympiad",                        "#5b3bb0"),
        ("AO",   "Achievers Olympiad",                    "#2e9e3e"),
        ("CIO",  "Commerce Olympiad",                     "#0a8fc7")
    ] %}

    {% set shown = [] %}
    {% for code, name, color in exams if (code in reg) or exam_dates.get(code) %}
        {% set _ = shown.append(code) %}
    {% endfor %}

    {% set body_mm = 84 %}
    {% set n = shown | length %}
    {% set row_h = ([body_mm / (n or 1), 16] | min) | round(2) %}
    {% set filler_h = (body_mm - (n * row_h)) | round(2) %}
    {% set sz = 'lg' if row_h >= 12 else ('md' if row_h >= 9 else 'sm') %}

    <div class="exam-panel sz-{{ sz }}">
        <table>
            <thead>
                <tr>
                    <th colspan="2">Exams</th>
                    <th class="dt">Exam Dates</th>
                </tr>
            </thead>
            <tbody>
                {% for code, name, color in exams if code in shown %}
                <tr style="height: {{ row_h }}mm;">
                    <td class="c-code"><span class="code" style="background:{{ color }}">{{ code }}</span></td>
                    <td class="name">{{ name }}</td>
                    <td class="c-date">
                        {% if exam_dates.get(code) %}
                        <span class="date">{{ frappe.utils.formatdate(exam_dates.get(code), "dd-mm-yyyy") }}</span>
                        {% endif %}
                    </td>
                </tr>
                {% endfor %}

                {% if filler_h > 1 %}
                <tr class="filler" style="height: {{ filler_h }}mm;">
                    <td colspan="3"></td>
                </tr>
                {% endif %}
            </tbody>
        </table>
    </div>

    {# ========================================================
       PAGE LABEL
       ======================================================== #}

    <div class="ticket-value page-label">
        {{ page_label or "" }}
    </div>

</div>
